def all_alta(apps, schema_editor):
    """An entry of the Alta Squadriglia of a reparto belongs to the one open for it, made by
    eventi 0017; its reparto is no longer needed. A condition on the Alta Squadriglia of a
    reparto asks for that one (DEC-440)."""
    VoceLibro = apps.get_model("cerimonie", "VoceLibro")
    Alta = apps.get_model("eventi", "AltaSquadriglia")
    Unita = apps.get_model("organizzazione", "Unita")

    def alta_di(reparto_id):
        reparto = Unita.objects.filter(pk=reparto_id).first()
        if reparto is None:
            return None
        reparti = [reparto.pk] + ([reparto.collegata_a_id] if reparto.collegata_a_id else [])
        alte = Alta.objects.filter(reparto_id__in=reparti).order_by("chiusa_il", "-pk")
        return alte.filter(chiusa_il=None).first() or alte.first()

    for voce in VoceLibro.objects.all():
        cambiata = False
        if voce.ambito == "ALTA_SQ" and voce.alta_id is None:
            reparto = voce.unita.values_list("pk", flat=True).first()
            alta = alta_di(reparto) if reparto else None
            if alta is not None:
                voce.alta = alta
                voce.unita.clear()
                cambiata = True
        gruppi = []
        for gruppo in voce.condizioni or []:
            nuovo = []
            for c in gruppo:
                if c.get("tipo") == "alta_squadriglia" and c.get("unita"):
                    alta = alta_di(c["unita"])
                    c = {"tipo": "alta_squadriglia", "alta": alta.pk} if alta else {"tipo": c["tipo"]}
                    cambiata = True
                nuovo.append(c)
            gruppi.append(nuovo)
        if cambiata:
            voce.condizioni = gruppi
            voce.save()


